              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="block text-gray-400 text-xs font-bold uppercase mb-1">Unidade de Medida</label>
                    <select 
                        value={formData.unit}
                        onChange={e => setFormData({...formData, unit: e.target.value as MeasureUnit})}
