                 {/* LINHAS MARKETPLACES */}
                 <div className="space-y-4">

                     {/* LINHA 3: iFood */}
                     <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end bg-gray-950/50 p-3 rounded-xl border border-gray-800/50">
