  Calculator, 
  ShoppingBag, 
  Tags,
  LogOut,
  Settings,
  Upload,
  X,
  Palette,
  RotateCcw,
  HelpCircle
} from 'lucide-react';
import { BACKGROUND_PALETTE } from '../constants';

interface SidebarProps {
  activeTab: string;
  setActiveTab: (tab: string) => void;
  onLogout?: () => void;
  bgColor: string;
  onBgColorChange: (color: string) => void;
}

const MENU_ITEMS = [
  { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
  { id: 'expenses', label: 'Despesas Fixas', icon: Receipt },
  { id: 'categories', label: 'Categorias', icon: Tags },
  { id: 'billing', label: 'Faturamento', icon: DollarSign },
  { id: 'dna', label: 'CFI da Empresa', icon: Dna },
  { id: 'ingredients', label: 'Insumos', icon: Beef },
  { id: 'products', label: 'Cardápio & Ficha', icon: UtensilsCrossed },
  { id: 'pricing', label: 'Preço de Venda', icon: Calculator },
  { id: 'profit', label: 'Lucro Atual', icon: ScrollText },
  { id: 'combos', label: 'Combos', icon: ShoppingBag },
  { id: 'help', label: 'Central de Ajuda', icon: HelpCircle },
];

const Sidebar: React.FC<SidebarProps> = ({ 
  activeTab, 
  setActiveTab, 
  onLogout, 
  bgColor,
  onBgColorChange
}) => {
  const { storeInfo, updateStoreInfo } = useApp();
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isPaletteOpen, setIsPaletteOpen] = useState(false);

  // Local state for editing
  const [editName, setEditName] = useState('');
  const [editAddress, setEditAddress] = useState('');
  const [editLogo, setEditLogo] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const openSettings = () => {
    setEditName(storeInfo.name);
    setEditAddress(storeInfo.address || '');
    setEditLogo(storeInfo.logo || '');
    setIsSettingsOpen(true);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditLogo(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveSettings = (e: React.FormEvent) => {
    e.preventDefault();
    updateStoreInfo({
      name: editName,
      address: editAddress,
      logo: editLogo
    });
    setIsSettingsOpen(false);
  };

  return (
    <>
      <div className="w-64 bg-white dark:bg-brand-dark border-r border-gray-200 dark:border-gray-800 h-screen flex flex-col fixed left-0 top-0 z-10 overflow-y-auto transition-colors duration-300 shadow-xl">
        <div className="p-6 border-b border-gray-200 dark:border-gray-800 flex items-center gap-3">
          <div className="w-10 h-10 bg-gray-100 dark:bg-gray-800 rounded-lg flex items-center justify-center shadow-lg overflow-hidden shrink-0 border border-gray-200 dark:border-gray-700">
            {storeInfo.logo ? (
               <img src={storeInfo.logo} alt="Logo" className="w-full h-full object-cover" />
            ) : (
               <UtensilsCrossed className="text-brand-red w-5 h-5" />
            )}
          </div>
          <div className="flex-1 min-w-0">
             <h1 className="text-sm font-bold text-gray-900 dark:text-white truncate leading-tight">{storeInfo.name}</h1>
             <button onClick={openSettings} className="text-[10px] text-gray-500 hover:text-brand-red flex items-center gap-1 transition-colors mt-0.5 font-bold uppercase">
               <Settings size={10} /> Configurar
             </button>
          </div>
        </div>

        <nav className="flex-1 p-4 space-y-1">
          {MENU_ITEMS.map((item) => {
            const Icon = item.icon;
            const isActive = activeTab === item.id;
            return (
              <button
                key={item.id}
                onClick={() => setActiveTab(item.id)}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all duration-200 ${
                  isActive 
                    ? 'bg-brand-red text-white shadow-lg shadow-red-900/20' 
                    : 'text-gray-500 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800 hover:text-gray-900 dark:hover:text-white'
                }`}
              >
                <Icon size={20} />
                <span className="font-medium">{item.label}</span>
              </button>
            );
          })}
        </nav>

        <div className="p-4 border-t border-gray-200 dark:border-gray-800 space-y-3">

          {/* Background Color Picker */}
          <div className="px-2">
             <div className="flex items-center justify-between mb-2 cursor-pointer" onClick={() => setIsPaletteOpen(!isPaletteOpen)}>
                <span className="text-xs font-bold text-gray-400 uppercase flex items-center gap-2"><Palette size={12}/> Cor Fundo</span>
                <span className="text-[10px] text-gray-500">{isPaletteOpen ? 'Ocultar' : 'Alterar'}</span>
             </div>

             {isPaletteOpen && (
               <div className="bg-gray-100 dark:bg-gray-800 rounded-lg p-2 grid grid-cols-4 gap-2 animate-fade-in">
                  {BACKGROUND_PALETTE.map((p) => (
                    <button
                      key={p.color}
                      onClick={() => onBgColorChange(p.color)}
                      className={`w-6 h-6 rounded-full border-2 transition-transform hover:scale-110 ${bgColor === p.color ? 'border-white ring-2 ring-brand-red' : 'border-transparent'}`}
                      style={{ backgroundColor: p.color }}
                      title={p.name}
                    />
                  ))}
                  <button 
                    onClick={() => onBgColorChange(BACKGROUND_PALETTE[0].color)}
                    className="col-span-4 text-[10px] text-gray-500 hover:text-brand-red flex items-center justify-center gap-1 mt-1 border-t border-gray-200 dark:border-gray-700 pt-1"
                  >
                    <RotateCcw size={10} /> Restaurar Padrão
                  </button>
               </div>
             )}
          </div>

          {onLogout && (
              <button 
                  onClick={onLogout}
                  className="w-full flex items-center gap-3 px-4 py-2 rounded-lg text-gray-500 dark:text-gray-400 hover:bg-gray-100 dark:hover:bg-gray-800 hover:text-gray-900 dark:hover:text-white transition-all duration-200 text-sm"
              >
                  <LogOut size={16} />
                  <span className="font-medium">Trocar Loja</span>
              </button>
          )}
          <div className="text-[10px] text-gray-400 text-center pt-2">
            v1.4.0 • Lucro Fácil
          </div>
        </div>
      </div>

      {/* Settings Modal */}
      {isSettingsOpen && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center z-50 p-4">
            <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-xl shadow-2xl w-full max-w-md animate-fade-in flex flex-col">
                <div className="p-6 border-b border-gray-200 dark:border-gray-800 flex justify-between items-center">
                    <h3 className="text-xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
                        <Settings size={20} className="text-brand-red" /> Dados da Loja
                    </h3>
                    <button onClick={() => setIsSettingsOpen(false)} className="text-gray-500 hover:text-gray-900 dark:hover:text-white"><X size={24}/></button>
                </div>
                <form onSubmit={handleSaveSettings} className="p-6 space-y-4">
                    <div className="flex justify-center mb-6">
                        <div 
                            className="w-24 h-24 rounded-full bg-gray-100 dark:bg-gray-800 border-2 border-dashed border-gray-300 dark:border-gray-600 flex items-center justify-center cursor-pointer hover:border-brand-red hover:bg-gray-200 dark:hover:bg-gray-700 transition relative overflow-hidden group"
                            onClick={() => fileInputRef.current?.click()}
                        >
                            {editLogo ? (
                                <img src={editLogo} alt="Logo" className="w-full h-full object-cover" />
                            ) : (
                                <div className="text-center text-gray-500">
                                    <Upload size={20} className="mx-auto mb-1" />
                                    <span className="text-[10px] uppercase font-bold">Logo</span>
                                </div>
                            )}
                            <div className="absolute inset-0 bg-black/50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition text-xs text-white font-bold">
                                Alterar
                            </div>
                        </div>
                        <input 
                            type="file" 
                            ref={fileInputRef} 
                            className="hidden" 
                            accept="image/*"
                            onChange={handleFileChange}
                        />
                    </div>

                    <div>
                        <label className="text-xs text-gray-500 uppercase font-bold mb-1 block">Nome da Loja</label>
                        <input 
                            type="text" 
                            value={editName}
                            onChange={(e) => setEditName(e.target.value)}
                            required
                            className="w-full bg-gray-50 dark:bg-gray-800 border border-gray-300 dark:border-gray-700 text-gray-900 dark:text-white rounded-lg p-3 outline-none focus:border-brand-red focus:ring-1 focus:ring-brand-red"
                        />
                    </div>

                    <div>
                        <label className="text-xs text-gray-500 uppercase font-bold mb-1 block">Endereço</label>
                        <input 
                            type="text" 
                            value={editAddress}
                            onChange={(e) => setEditAddress(e.target.value)}
                            className="w-full bg-gray-50 dark:bg-gray-800 border border-gray-300 dark:border-gray-700 text-gray-900 dark:text-white rounded-lg p-3 outline-none focus:border-brand-red focus:ring-1 focus:ring-brand-red"
                        />
                    </div>

                    <div className="pt-4 flex gap-3">
                        <button type="button" onClick={() => setIsSettingsOpen(false)} className="flex-1 py-3 bg-gray-200 dark:bg-gray-800 text-gray-700 dark:text-white font-bold rounded-lg hover:bg-gray-300 dark:hover:bg-gray-700 transition">Cancelar</button>
                        <button type="submit" className="flex-1 py-3 bg-brand-red text-white font-bold rounded-lg hover:bg-red-700 transition shadow-lg shadow-red-900/20">Salvar Alterações</button>
                    </div>
                </form>
            </div>
        </div>
      )}
    </>
  );
};

export default Sidebar;

import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { Product } from '../types';
import { Plus, Trash, Edit2, Search, FileText, X, ChefHat, HelpCircle } from 'lucide-react';

const Products: React.FC = () => {
  const { products, ingredients, addProduct, updateProduct, deleteProduct, getProductCMV, getIngredientRealCost } = useApp();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [showHelp, setShowHelp] = useState(false);

  // Form State for Modal
  const [prodName, setProdName] = useState('');
  const [prodCategory, setProdCategory] = useState('');

  const openNewProductModal = () => {
    setEditingProduct(null);
    setProdName('');
    setProdCategory('Geral');
    setIsModalOpen(true);
  };

  const openRecipeModal = (prod: Product) => {
    setEditingProduct(prod);
    setProdName(prod.name);
    setProdCategory(prod.category);
    setIsModalOpen(true);
  };

  const handleSaveProduct = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingProduct) {
      updateProduct(editingProduct.id, { name: prodName, category: prodCategory });
    } else {
      addProduct({
        id: Date.now().toString(),
        name: prodName,
        category: prodCategory,
        ingredients: []
      });
      setIsModalOpen(false); // Close if new, keep open if editing recipe
    }
  };

  const handleDeleteProduct = (id: string, name: string) => {
    if (window.confirm(`Tem certeza que deseja excluir "${name}" do cardápio?`)) {
        deleteProduct(id);
    }
  };

  const addIngredientToProduct = (ingredientId: string) => {
    if (!editingProduct) return;
    const currentIngs = editingProduct.ingredients || [];
    const newIngs = [...currentIngs, { ingredientId, quantity: 1 }];
    updateProduct(editingProduct.id, { ingredients: newIngs });
    // Update local state to reflect changes immediately in modal
    setEditingProduct({ ...editingProduct, ingredients: newIngs });
  };

  const updateProductIngredientQty = (index: number, newQty: number) => {
    if (!editingProduct) return;
    const newIngs = [...editingProduct.ingredients];
    newIngs[index].quantity = newQty;
    updateProduct(editingProduct.id, { ingredients: newIngs });
    setEditingProduct({ ...editingProduct, ingredients: newIngs });
  };

  const removeProductIngredient = (index: number) => {
    if (!editingProduct) return;
    const newIngs = editingProduct.ingredients.filter((_, i) => i !== index);
    updateProduct(editingProduct.id, { ingredients: newIngs });
    setEditingProduct({ ...editingProduct, ingredients: newIngs });
  };

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-6 animate-fade-in pb-20">
       <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
          <div>
            <div className="flex items-center gap-2">
                <h2 className="text-3xl font-bold text-gray-900 dark:text-white uppercase">Itens do Cardápio</h2>
                <button 
                    onClick={() => setShowHelp(!showHelp)} 
                    className="text-gray-400 hover:text-brand-red transition-colors"
                    title="Ajuda"
                >
                    <HelpCircle size={20} />
                </button>
            </div>
            <p className="text-gray-500 dark:text-gray-400">Gerencie seus produtos e acesse as fichas técnicas detalhadas.</p>

            {showHelp && (
            <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-500/30 p-4 rounded-xl relative animate-fade-in mt-4 max-w-3xl shadow-sm">
                <button onClick={() => setShowHelp(false)} className="absolute top-2 right-2 text-blue-400 hover:text-blue-300"><X size={16}/></button>
                <h4 className="font-bold text-blue-700 dark:text-blue-300 mb-2 flex items-center gap-2"><HelpCircle size={16}/> Montando o Produto</h4>
                <p className="text-sm text-blue-800 dark:text-blue-200 leading-relaxed">
                    Aqui você cria a receita do seu prato.
                    <br/>
                    1. Clique em <strong>Novo Item</strong> para criar o produto.
                    <br/>
                    2. Depois, clique em <strong>Ficha Técnica</strong> para adicionar os insumos que compõem este prato.
                    <br/>
                    3. O sistema calculará automaticamente o <strong>CMV</strong> (Custo de Mercadoria Vendida), ou seja, quanto custa em matéria-prima para produzir 1 unidade.
                </p>
            </div>
           )}
          </div>

          <div className="flex items-center gap-4 w-full md:w-auto">
             <div className="relative flex-1 md:w-64">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500" size={18} />
                <input 
                    type="text" 
                    placeholder="Buscar produto..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="w-full bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 text-gray-900 dark:text-white rounded-lg pl-10 pr-4 py-2 focus:ring-2 focus:ring-brand-red outline-none shadow-sm"
                />
            </div>
            <button 
              onClick={openNewProductModal}
              className="bg-brand-red hover:bg-red-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 font-bold transition shadow-lg shadow-red-900/20"
            >
              <Plus size={18} /> <span className="hidden sm:inline">NOVO ITEM</span>
            </button>
          </div>
       </div>

       {/* PRODUCT LIST TABLE */}
       <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-xl overflow-hidden shadow-xl">
          <div className="overflow-x-auto">
             <table className="w-full text-left">
                <thead className="bg-gray-50 dark:bg-[#0f111a] text-gray-500 dark:text-gray-400 text-xs uppercase font-bold tracking-wider">
                   <tr>
                      <th className="px-6 py-4">Nome do Produto</th>
                      <th className="px-6 py-4">Categoria</th>
                      <th className="px-6 py-4 text-center">Insumos</th>
                      <th className="px-6 py-4 text-right">CMV (R$)</th>
                      <th className="px-6 py-4 text-right">Ação</th>
                   </tr>
                </thead>
                <tbody className="divide-y divide-gray-100 dark:divide-gray-800 text-sm">
                   {filteredProducts.map(prod => {
                      const cmv = getProductCMV(prod);
                      return (
                         <tr key={prod.id} className="hover:bg-gray-50 dark:hover:bg-gray-800/50 transition group">
                            <td className="px-6 py-4 font-bold text-gray-900 dark:text-white text-base">{prod.name}</td>
                            <td className="px-6 py-4 text-gray-500 dark:text-gray-400">
                               <span className="bg-gray-100 dark:bg-gray-800 px-2 py-1 rounded text-xs border border-gray-200 dark:border-gray-700">{prod.category || 'Geral'}</span>
                            </td>
                            <td className="px-6 py-4 text-center text-gray-500">{prod.ingredients.length}</td>
                            <td className="px-6 py-4 text-right font-mono font-bold text-brand-red">R$ {cmv.toFixed(2)}</td>
                            <td className="px-6 py-4">
                               <div className="flex justify-end items-center gap-2">
                                  <button 
                                    onClick={() => openRecipeModal(prod)}
                                    className="bg-white dark:bg-gray-800 hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-700 dark:text-white px-3 py-1.5 rounded flex items-center gap-2 text-xs font-bold transition border border-gray-200 dark:border-gray-700 shadow-sm"
                                  >
                                     <FileText size={14} /> Ficha Técnica
                                  </button>
                                  <button
                                     onClick={() => handleDeleteProduct(prod.id, prod.name)}
                                     className="bg-red-50 dark:bg-red-900/20 hover:bg-red-100 dark:hover:bg-red-900/40 text-red-600 dark:text-red-500 px-3 py-1.5 rounded flex items-center gap-2 text-xs font-bold transition border border-red-200 dark:border-red-900/30"
                                     title="Excluir Produto"
                                  >
                                     <Trash size={14} />
                                  </button>
                               </div>
                            </td>
                         </tr>
                      );
                   })}
                </tbody>
             </table>
          </div>
       </div>

       {/* RECIPE CARD MODAL (Ficha Técnica) */}
       {isModalOpen && (
         <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center z-50 p-4">
            <div className="bg-white dark:bg-gray-900 w-full max-w-4xl h-[90vh] rounded-xl border border-gray-200 dark:border-gray-800 shadow-2xl animate-fade-in flex flex-col">

               {/* Header */}
               <div className="p-6 border-b border-gray-200 dark:border-gray-800 flex justify-between items-start">
                  <div>
                     <h3 className="text-xl font-bold text-gray-900 dark:text-white flex items-center gap-2 uppercase">
                        <ChefHat size={24} className="text-brand-red" />
                        {editingProduct ? 'Ficha Técnica' : 'Novo Produto'}
                     </h3>
                     <p className="text-gray-500 dark:text-gray-400 text-sm mt-1">
                        {editingProduct ? `Editando composição de: ${editingProduct.name}` : 'Cadastre um novo item no cardápio'}
                     </p>
                  </div>
                  <button onClick={() => setIsModalOpen(false)} className="text-gray-500 hover:text-gray-900 dark:hover:text-white"><X size={24}/></button>
               </div>

               {/* Body */}
               <div className="flex-1 overflow-y-auto p-6 space-y-6">

                  {/* Basic Info */}
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-gray-50 dark:bg-gray-950 p-4 rounded-xl border border-gray-200 dark:border-gray-800">
                     <div>
                        <label className="text-xs text-gray-500 dark:text-gray-400 uppercase font-bold mb-1 block">Nome do Produto</label>
                        <input 
                           type="text" 
