import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { Calculator, AlertTriangle, HelpCircle, X } from 'lucide-react';
import { Product } from '../types';

const Pricing: React.FC = () => {
  const { 
    products, 
    getProductCMV, 
    cfi, 
    platformConfig, 
    calculateFixedCostPercent,
    updateProduct
  } = useApp();
  const [showHelp, setShowHelp] = useState(false);

  const fixedCostPct = calculateFixedCostPercent();

  // Logic from CFI Page: Avg Card + Tax + Royalties + Marketing + Voucher
  const avgCardRate = (cfi.debitTax + cfi.creditTax) / 2;
  const variableCostsPct = avgCardRate + cfi.tax + cfi.royalties + cfi.marketing + cfi.voucherTax;

  // Total Cost Structure (CFI)
  const totalCfiCost = fixedCostPct + variableCostsPct;

  // Formula: PV Loja = CMV / (1 - (TotalCFI% + Profit%) / 100)
  const calculateStorePrice = (cmv: number, profitMargin: number) => {
    const totalDeductions = (totalCfiCost + profitMargin) / 100;
    if (totalDeductions >= 1) return 0; 
    return cmv / (1 - totalDeductions);
  };

  // OFFICIAL MARKETPLACE FORMULA (Denominator Method)
  // PV = (PV_Loja + Delivery + CI + Coupon) / (1 - TotalFees)
  const calculateMarketplacePrice = (
      pvLoja: number, 
      feesPct: number, 
      delivery: number, 
      ci: number, 
      coupon: number
  ) => {
      const totalFees = feesPct / 100;
      const denominator = 1 - totalFees;
      if (denominator <= 0) return 0; // Inviable fees

      // CI and Coupon are costs added to the base to preserve the net PV Loja
      const numerator = pvLoja + delivery + ci + coupon;
      return numerator / denominator;
  };

  const handleUpdate = (productId: string, section: 'pricing', key: string, value: number) => {
      const product = products.find(p => p.id === productId);
      if (!product) return;

      const newPricing = { ...product.pricing };

      // Parse key path (e.g., 'ifood.fee')
      if (key.includes('.')) {
          const [parent, child] = key.split('.');
          // @ts-ignore
          newPricing[parent] = { ...newPricing[parent], [child]: value };
      } else {
          // @ts-ignore
          newPricing[key] = value;
      }

      updateProduct(productId, { pricing: newPricing });
  };


  return (
    <div className="space-y-6 pb-20 animate-fade-in">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <div className="flex items-center gap-2">
            <h2 className="text-3xl font-bold text-gray-900 dark:text-white mb-2 uppercase">Preço de Venda</h2>
            <button 
                onClick={() => setShowHelp(!showHelp)} 
                className="text-gray-400 hover:text-brand-red transition-colors"
                title="Ajuda"
            >
                <HelpCircle size={20} />
            </button>
          </div>
          <p className="text-gray-500 dark:text-gray-400">Precificação oficial via denominador (iFood/99/Keeta) para garantir margem líquida.</p>

          {showHelp && (
            <div className="bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-500/30 p-4 rounded-xl relative animate-fade-in mt-4 max-w-3xl shadow-sm">
                <button onClick={() => setShowHelp(false)} className="absolute top-2 right-2 text-blue-400 hover:text-blue-300"><X size={16}/></button>
                <h4 className="font-bold text-blue-700 dark:text-blue-300 mb-2 flex items-center gap-2"><HelpCircle size={16}/> Como funciona o Cálculo?</h4>
                <p className="text-sm text-blue-800 dark:text-blue-200 leading-relaxed">
                    Nesta tela, nós sugerimos o preço ideal para que você tenha lucro real.
                    <br/><br/>
                    <strong>PV Loja:</strong> Calculamos o preço base somando o custo do produto (CMV) + seu custo fixo (CFI) + a margem de lucro que você deseja.
                    <br/><br/>
                    <strong>PV Marketplace (iFood/99):</strong> Pegamos o PV Loja e adicionamos as taxas da plataforma "por fora" (fórmula do denominador). 
                    <br/>
                    <em>Isso garante que, após o iFood descontar as taxas dele, sobre no seu bolso exatamente o valor do PV Loja.</em>
                </p>
            </div>
           )}
        </div>

        {/* CFI Summary Box */}
