            <div>
                <span className="block text-[10px] text-gray-500 uppercase font-bold">CFI Total (Fixo+Var)</span>
                <span className="text-xl font-bold text-brand-red">{totalCfiCost.toFixed(2)}%</span>
            </div>
        </div>
      </div>

