      icon: AlertTriangle,
      color: 'text-brand-red',
      content: `
        <p>Na aba <strong>Preço de Venda</strong>, a mágica acontece. O sistema junta:</p>
        <ul class="list-disc list-inside ml-2 mt-2 text-gray-500 dark:text-gray-400">
            <li>Custo do Produto (CMV)</li>
            <li>Custo Fixo (CFI)</li>
            <li>Lucro que você quer (Margem)</li>
        </ul>
        <br/>
        <strong>Preço para iFood/Delivery:</strong>
        <p>O sistema calcula um preço diferente para o iFood. Ele adiciona as taxas da plataforma "por fora" para garantir que, depois que o iFood descontar a parte dele, sobre no seu bolso exatamente o mesmo valor que sobraria se vendesse no balcão.</p>
      `
    }
  ];

  const FAQ_ITEMS = [
    {
      id: 'faq1',
      question: 'O que é CFI e por que ele é tão importante?',
      answer: 'CFI significa <strong>Custo Fixo Integrado</strong>. Imagine que sua loja não vendeu nada hoje. O aluguel e a internet precisam ser pagos mesmo assim, certo? O CFI calcula qual porcentagem de cada hambúrguer vendido serve apenas para pagar essas contas. Se você ignorar o CFI, pode achar que está lucrando quando na verdade está apenas pagando contas.'
    },
    {
      id: 'faq2',
      question: 'Por que o preço do iFood fica tão mais caro?',
      answer: 'Isso é proposital para proteger seu lucro. O iFood cobra taxas altas (entre 12% a 27%). Se você vender pelo mesmo preço do balcão, a taxa do iFood vai comer todo o seu lucro. Nosso sistema usa um cálculo de "divisor" para garantir que o cliente pague a taxa do iFood, não você.'
    },
    {
      id: 'faq3',
      question: 'Devo cadastrar o salário dos funcionários onde?',
      answer: 'Salários fixos (gerente, atendente fixo, cozinheiro contratado) entram na aba <strong>Despesas Fixas</strong>. Já se você paga um freelancer por dia (ex: R$ 50 a diária), isso pode ser considerado custo variável, mas para simplificar, a maioria das hamburguerias lança tudo em Despesas Fixas para garantir que o custo esteja coberto na média mensal.'
    },
    {
      id: 'faq4',
      question: 'O que é a "Perda %" no cadastro de insumos?',
      answer: 'É a parte do ingrediente que vai para o lixo durante o preparo. Exemplo: Ao limpar uma peça de Alcatra, você tira gordura e nervos. Se comprou 1kg mas só aproveitou 800g, teve 20% de perda. Se não informar isso, você estará cobrando menos do que deveria, pois pagou pela gordura que jogou fora.'
    },
    {
      id: 'faq5',
      question: 'Como calcular o custo do gás ou óleo de fritura?',
      answer: 'Esses são difíceis de medir por unidade. A melhor prática é lançar o valor total da conta de Gás na aba <strong>Despesas Fixas</strong>. Assim, ele entra no cálculo global do CFI e é rateado entre todos os produtos vendidos.'
    },
    {
        id: 'faq6',
        question: 'O sistema salva meus dados?',
        answer: 'Sim! Os dados ficam salvos no seu navegador. Se você limpar o cache do navegador ou trocar de computador, os dados podem não aparecer. Recomendamos sempre usar o mesmo dispositivo.'
    }
  ];

  // --- LÓGICA DE BUSCA ---
  const filteredManual = useMemo(() => {
    if (!searchTerm) return MANUAL_STEPS;
    const lower = searchTerm.toLowerCase();
    return MANUAL_STEPS.filter(s => 
        s.title.toLowerCase().includes(lower) || 
        s.content.toLowerCase().includes(lower)
    );
  }, [searchTerm]);

  const filteredFaq = useMemo(() => {
    if (!searchTerm) return FAQ_ITEMS;
    const lower = searchTerm.toLowerCase();
    return FAQ_ITEMS.filter(f => 
        f.question.toLowerCase().includes(lower) || 
        f.answer.toLowerCase().includes(lower)
    );
  }, [searchTerm]);

  // Se estiver buscando, mostra ambas as abas se tiver resultados
  const isSearching = searchTerm.length > 0;

  return (
    <div className="space-y-8 animate-fade-in pb-20">

      {/* HEADER & SEARCH - UPDATED FOR DYNAMIC THEME */}
      <div className="bg-white dark:bg-gradient-to-r dark:from-brand-dark dark:to-gray-900 border border-gray-200 dark:border-gray-800 p-8 rounded-2xl relative overflow-hidden shadow-xl">
          {/* Subtle decoration for light mode */}
          <div className="absolute top-0 right-0 w-64 h-64 bg-gray-100 rounded-full blur-[80px] -mr-16 -mt-16 pointer-events-none dark:hidden"></div>
          {/* Subtle decoration for dark mode */}
          <div className="hidden dark:block absolute top-0 right-0 w-64 h-64 bg-brand-red/10 rounded-full blur-[80px] -mr-16 -mt-16 pointer-events-none"></div>

          <div className="relative z-10 max-w-3xl mx-auto text-center space-y-6">
              <h1 className="text-3xl md:text-4xl font-bold text-gray-900 dark:text-white mb-2">Como podemos ajudar você hoje?</h1>
              <p className="text-gray-500 dark:text-gray-400 text-lg">Digite sua dúvida ou navegue pelo manual completo.</p>

              <div className="relative group">
                  <div className="absolute -inset-1 bg-gradient-to-r from-brand-red to-purple-600 rounded-xl blur opacity-10 dark:opacity-25 group-hover:opacity-30 dark:group-hover:opacity-50 transition duration-200"></div>
                  <div className="relative flex items-center bg-gray-50 dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl p-4 shadow-sm dark:shadow-xl">
                      <Search className="text-gray-400 mr-3" size={24} />
                      <input 
                        type="text" 
                        placeholder="Ex: Como calcular iFood, O que é CFI, Insumos..." 
                        className="w-full bg-transparent text-gray-900 dark:text-white text-lg outline-none placeholder-gray-400 dark:placeholder-gray-600"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                      />
                      {searchTerm && (
                          <button onClick={() => setSearchTerm('')} className="text-gray-400 hover:text-gray-600 dark:hover:text-white">Limpar</button>
                      )}
                  </div>
              </div>
          </div>
      </div>

      {/* TABS (Only show if not searching) */}
      {!isSearching && (
          <div className="flex justify-center gap-4 border-b border-gray-200 dark:border-gray-800 pb-1">
              <button 
                onClick={() => setActiveTab('manual')}
                className={`pb-3 px-6 text-sm font-bold uppercase tracking-wider transition border-b-2 ${activeTab === 'manual' ? 'border-brand-red text-gray-900 dark:text-white' : 'border-transparent text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'}`}
              >
                  Manual Completo
              </button>
              <button 
                onClick={() => setActiveTab('faq')}
                className={`pb-3 px-6 text-sm font-bold uppercase tracking-wider transition border-b-2 ${activeTab === 'faq' ? 'border-brand-red text-gray-900 dark:text-white' : 'border-transparent text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'}`}
              >
                  Perguntas Frequentes
              </button>
          </div>
      )}

      <div className="max-w-4xl mx-auto space-y-8">

          {/* MANUAL SECTION */}
          {(activeTab === 'manual' || isSearching) && filteredManual.length > 0 && (
              <div className="space-y-4">
                  {isSearching && <h3 className="text-gray-500 font-bold uppercase text-xs mb-2 pl-2">Resultados no Manual</h3>}
                  {filteredManual.map((step) => {
                      const Icon = step.icon;
                      const isOpen = expandedItems[step.id] || isSearching; // Auto expand on search
                      return (
                          <div key={step.id} className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-xl overflow-hidden transition-all duration-300 hover:border-gray-300 dark:hover:border-gray-700 shadow-sm">
                              <button 
                                onClick={() => toggleItem(step.id)}
                                className="w-full flex items-center justify-between p-6 text-left focus:outline-none"
                              >
                                  <div className="flex items-center gap-4">
                                      <div className={`p-3 rounded-lg bg-gray-100 dark:bg-gray-800 ${step.color}`}>
                                          <Icon size={24} />
                                      </div>
                                      <h3 className="text-lg font-bold text-gray-900 dark:text-white">{step.title}</h3>
                                  </div>
                                  <div className="text-gray-400">
                                      {isOpen ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
                                  </div>
                              </button>

                              {isOpen && (
                                  <div className="px-6 pb-6 pt-0 ml-0 md:ml-20">
                                      <div 
                                        className="text-gray-600 dark:text-gray-300 text-base leading-relaxed border-t border-gray-100 dark:border-gray-800 pt-4"
                                        dangerouslySetInnerHTML={{ __html: step.content }} 
                                      />
                                  </div>
                              )}
                          </div>
                      );
                  })}
              </div>
          )}

          {/* FAQ SECTION */}
          {(activeTab === 'faq' || isSearching) && filteredFaq.length > 0 && (
              <div className="space-y-4">
                  {isSearching && <h3 className="text-gray-500 font-bold uppercase text-xs mb-2 pl-2 mt-8">Resultados nas Perguntas (FAQ)</h3>}
                  {filteredFaq.map((faq) => {
                      const isOpen = expandedItems[faq.id];
                      return (
                          <div key={faq.id} className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-xl overflow-hidden transition-all">
                              <button 
                                onClick={() => toggleItem(faq.id)}
                                className="w-full flex items-center justify-between p-5 text-left hover:bg-gray-50 dark:hover:bg-gray-800/50 transition focus:outline-none"
                              >
                                  <span className="font-bold text-gray-800 dark:text-gray-200 flex items-center gap-3">
                                      <HelpCircle size={18} className="text-brand-red shrink-0" />
                                      {faq.question}
                                  </span>
                                  <span className="text-gray-400 shrink-0 ml-4">
                                      {isOpen ? <ChevronUp size={18} /> : <ChevronDown size={18} />}
                                  </span>
                              </button>
                              {isOpen && (
                                  <div className="px-5 pb-5 pt-2 pl-12">
                                      <div 
                                        className="text-gray-600 dark:text-gray-400 text-sm leading-relaxed bg-gray-50 dark:bg-black/20 p-4 rounded-lg border border-gray-200 dark:border-gray-700/50"
                                        dangerouslySetInnerHTML={{ __html: faq.answer }}
                                      />
                                  </div>
                              )}
                          </div>
                      );
                  })}
              </div>
          )}

          {/* EMPTY STATE */}
          {isSearching && filteredManual.length === 0 && filteredFaq.length === 0 && (
              <div className="text-center py-20">
                  <div className="bg-gray-200 dark:bg-gray-800 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 text-gray-500">
                      <Search size={32} />
                  </div>
                  <h3 className="text-xl font-bold text-gray-900 dark:text-white mb-2">Nenhum resultado encontrado</h3>
                  <p className="text-gray-500">Tente buscar por palavras-chave como "custo", "ifood" ou "lucro".</p>
                  <button 
                    onClick={() => setSearchTerm('')}
                    className="mt-6 text-brand-red font-bold hover:underline"
                  >
                      Limpar busca
                  </button>
              </div>
          )}

      </div>
    </div>
  );
};

export default Help;

import React, { useState, useRef } from 'react';
import { useApp } from '../context/AppContext';
import { 
  LayoutDashboard, 
  Receipt, 
  DollarSign, 
  Dna, 
  Beef, 
  UtensilsCrossed, 
  ScrollText, 
  Calculator, 
  ShoppingBag, 
  Tags,
  LogOut,
  Settings,
  Upload,
  X,
  Palette,
  RotateCcw,
  HelpCircle
} from 'lucide-react';
import { BACKGROUND_PALETTE } from '../constants';

interface SidebarProps {
  activeTab: string;
  setActiveTab: (tab: string) => void;
  onLogout?: () => void;
  bgColor: string;
  onBgColorChange: (color: string) => void;
}

const MENU_ITEMS = [
  { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
  { id: 'expenses', label: 'Despesas Fixas', icon: Receipt },
  { id: 'categories', label: 'Categorias', icon: Tags },
  { id: 'billing', label: 'Faturamento', icon: DollarSign },
  { id: 'dna', label: 'CFI da Empresa', icon: Dna },
  { id: 'ingredients', label: 'Insumos', icon: Beef },
  { id: 'products', label: 'Cardápio & Ficha', icon: UtensilsCrossed },
  { id: 'pricing', label: 'Preço de Venda', icon: Calculator },
  { id: 'profit', label: 'Lucro Atual', icon: ScrollText },
  { id: 'combos', label: 'Combos', icon: ShoppingBag },
  { id: 'help', label: 'Central de Ajuda', icon: HelpCircle },
];

const Sidebar: React.FC<SidebarProps> = ({ 
  activeTab, 
  setActiveTab, 
  onLogout, 
  bgColor,
  onBgColorChange
}) => {
  const { storeInfo, updateStoreInfo } = useApp();
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isPaletteOpen, setIsPaletteOpen] = useState(false);

  // Local state for editing
  const [editName, setEditName] = useState('');
  const [editAddress, setEditAddress] = useState('');
  const [editLogo, setEditLogo] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const openSettings = () => {
    setEditName(storeInfo.name);
    setEditAddress(storeInfo.address || '');
    setEditLogo(storeInfo.logo || '');
    setIsSettingsOpen(true);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setEditLogo(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveSettings = (e: React.FormEvent) => {
    e.preventDefault();
    updateStoreInfo({
      name: editName,
      address: editAddress,
      logo: editLogo
    });
    setIsSettingsOpen(false);
  };

  return (
    <>
      <div 
        className="w-64 border-r border-gray-200 dark:border-gray-800 h-screen flex flex-col fixed left-0 top-0 z-10 overflow-y-auto transition-colors duration-300 shadow-xl"
        style={{ backgroundColor: bgColor }}
      >
        <div className="p-6 border-b border-gray-200 dark:border-gray-800 flex items-center gap-3">
          <div className="w-10 h-10 bg-white/50 dark:bg-black/20 rounded-lg flex items-center justify-center shadow-lg overflow-hidden shrink-0 border border-gray-200 dark:border-white/10">
            {storeInfo.logo ? (
               <img src={storeInfo.logo} alt="Logo" className="w-full h-full object-cover" />
            ) : (
               <UtensilsCrossed className="text-brand-red w-5 h-5" />
            )}
          </div>
          <div className="flex-1 min-w-0">
             <h1 className="text-sm font-bold text-gray-900 dark:text-white truncate leading-tight">{storeInfo.name}</h1>
             <button onClick={openSettings} className="text-[10px] text-gray-500 hover:text-brand-red flex items-center gap-1 transition-colors mt-0.5 font-bold uppercase">
               <Settings size={10} /> Configurar
             </button>
          </div>
        </div>

        <nav className="flex-1 p-4 space-y-1">
          {MENU_ITEMS.map((item) => {
            const Icon = item.icon;
            const isActive = activeTab === item.id;
            return (
              <button
                key={item.id}
                onClick={() => setActiveTab(item.id)}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg transition-all duration-200 ${
                  isActive 
                    ? 'bg-brand-red text-white shadow-lg shadow-red-900/20' 
                    : 'text-gray-500 dark:text-gray-300 hover:bg-black/5 dark:hover:bg-white/10 hover:text-gray-900 dark:hover:text-white'
                }`}
              >
                <Icon size={20} />
                <span className="font-medium">{item.label}</span>
              </button>
            );
          })}
        </nav>

        <div className="p-4 border-t border-gray-200 dark:border-gray-800 space-y-3">

          {/* Background Color Picker */}
          <div className="px-2">
             <div className="flex items-center justify-between mb-2 cursor-pointer group" onClick={() => setIsPaletteOpen(!isPaletteOpen)}>
                <span className="text-xs font-bold text-gray-400 dark:text-gray-500 group-hover:text-brand-red uppercase flex items-center gap-2 transition-colors"><Palette size={12}/> Cor Fundo</span>
                <span className="text-[10px] text-gray-500">{isPaletteOpen ? 'Ocultar' : 'Alterar'}</span>
             </div>

             {isPaletteOpen && (
               <div className="bg-black/5 dark:bg-black/20 rounded-lg p-2 grid grid-cols-4 gap-2 animate-fade-in border border-gray-200 dark:border-white/5">
                  {BACKGROUND_PALETTE.map((p) => (
                    <button
                      key={p.color}
                      onClick={() => onBgColorChange(p.color)}
                      className={`w-6 h-6 rounded-full border-2 transition-transform hover:scale-110 ${bgColor === p.color ? 'border-white ring-2 ring-brand-red' : 'border-transparent'}`}
                      style={{ backgroundColor: p.color }}
                      title={p.name}
                    />
                  ))}
                  <button 
                    onClick={() => onBgColorChange(BACKGROUND_PALETTE[0].color)}
                    className="col-span-4 text-[10px] text-gray-500 hover:text-brand-red flex items-center justify-center gap-1 mt-1 border-t border-gray-200 dark:border-white/5 pt-1"
                  >
                    <RotateCcw size={10} /> Restaurar Padrão
                  </button>
               </div>
             )}
          </div>

          {onLogout && (
              <button 
                  onClick={onLogout}
                  className="w-full flex items-center gap-3 px-4 py-2 rounded-lg text-gray-500 dark:text-gray-400 hover:bg-black/5 dark:hover:bg-white/10 hover:text-gray-900 dark:hover:text-white transition-all duration-200 text-sm"
              >
                  <LogOut size={16} />
                  <span className="font-medium">Trocar Loja</span>
              </button>
          )}
          <div className="text-[10px] text-gray-400 dark:text-gray-500 text-center pt-2 opacity-50">
            v1.4.2 • Lucro Fácil
          </div>
        </div>
      </div>

      {/* Settings Modal */}
      {isSettingsOpen && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center z-50 p-4">
            <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-xl shadow-2xl w-full max-w-md animate-fade-in flex flex-col">
                <div className="p-6 border-b border-gray-200 dark:border-gray-800 flex justify-between items-center">
                    <h3 className="text-xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
                        <Settings size={20} className="text-brand-red" /> Dados da Loja
                    </h3>
                    <button onClick={() => setIsSettingsOpen(false)} className="text-gray-500 hover:text-gray-900 dark:hover:text-white"><X size={24}/></button>
                </div>
                <form onSubmit={handleSaveSettings} className="p-6 space-y-4">
                    <div className="flex justify-center mb-6">
                        <div 
                            className="w-24 h-24 rounded-full bg-gray-100 dark:bg-gray-800 border-2 border-dashed border-gray-300 dark:border-gray-600 flex items-center justify-center cursor-pointer hover:border-brand-red hover:bg-gray-200 dark:hover:bg-gray-700 transition relative overflow-hidden group"
                            onClick={() => fileInputRef.current?.click()}
                        >
                            {editLogo ? (
                                <img src={editLogo} alt="Logo" className="w-full h-full object-cover" />
                            ) : (
                                <div className="text-center text-gray-500">
                                    <Upload size={20} className="mx-auto mb-1" />
                                    <span className="text-[10px] uppercase font-bold">Logo</span>
                                </div>
                            )}
                            <div className="absolute inset-0 bg-black/50 flex items-center justify-center opacity-0 group-hover:opacity-100 transition text-xs text-white font-bold">
                                Alterar
                            </div>
                        </div>
                        <input 
                            type="file" 
                            ref={fileInputRef} 
                            className="hidden" 
                            accept="image/*"
                            onChange={handleFileChange}
                        />
                    </div>

                    <div>
                        <label className="text-xs text-gray-500 uppercase font-bold mb-1 block">Nome da Loja</label>
                        <input 
                            type="text" 
                            value={editName}
                            onChange={(e) => setEditName(e.target.value)}
                            required
                            className="w-full bg-gray-50 dark:bg-gray-800 border border-gray-300 dark:border-gray-700 text-gray-900 dark:text-white rounded-lg p-3 outline-none focus:border-brand-red focus:ring-1 focus:ring-brand-red"
                        />
                    </div>

                    <div>
                        <label className="text-xs text-gray-500 uppercase font-bold mb-1 block">Endereço</label>
                        <input 
                            type="text" 
                            value={editAddress}
                            onChange={(e) => setEditAddress(e.target.value)}
                            className="w-full bg-gray-50 dark:bg-gray-800 border border-gray-300 dark:border-gray-700 text-gray-900 dark:text-white rounded-lg p-3 outline-none focus:border-brand-red focus:ring-1 focus:ring-brand-red"
                        />
                    </div>

                    <div className="pt-4 flex gap-3">
                        <button type="button" onClick={() => setIsSettingsOpen(false)} className="flex-1 py-3 bg-gray-200 dark:bg-gray-800 text-gray-700 dark:text-white font-bold rounded-lg hover:bg-gray-300 dark:hover:bg-gray-700 transition">Cancelar</button>
                        <button type="submit" className="flex-1 py-3 bg-brand-red text-white font-bold rounded-lg hover:bg-red-700 transition shadow-lg shadow-red-900/20">Salvar Alterações</button>
                    </div>
                </form>
            </div>
        </div>
      )}
    </>
  );
};

export default Sidebar;

import React, { useState, useMemo } from 'react';
import { Search, BookOpen, HelpCircle, ChevronDown, ChevronUp, CheckCircle, AlertTriangle, Lightbulb, ExternalLink } from 'lucide-react';

const Help: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'manual' | 'faq'>('manual');
  const [searchTerm, setSearchTerm] = useState('');
  const [expandedItems, setExpandedItems] = useState<Record<string, boolean>>({});

  const toggleItem = (id: string) => {
    setExpandedItems(prev => ({ ...prev, [id]: !prev[id] }));
